module explosion_probability(\n    input [3:0] our_health1,\n    input [3:0] our_health2,\n    input [3:0] opp_health1,\n    input [3:0] opp_health2,\n    input [3:0] damage,\n    output reg [31:0] probability_out\n);\n\n    // Sort our minions health descending\n    reg [3:0] our_sorted1, our_sorted2;\n    always @(*) begin\n        if (our_health1 >= our_health2) begin\n            our_sorted1 = our_health1;\n            our_sorted2 = our_health2;\n        end else begin\n            our_sorted1 = our_health2;\n            our_sorted2 = our_health1;\n        end\n    end\n\n    // Sort opponent minions health descending\n    reg [3:0] opp_sorted1, opp_sorted2;\n    always @(*) begin\n        if (opp_health1 >= opp_health2) begin\n            opp_sorted1 = opp_health1;\n            opp_sorted2 = opp_health2;\n        end else begin\n            opp_sorted1 = opp_health2;\n            opp_sorted2 = opp_health1;\n        end\n    end\n\n    // Map sorted health to state index (0..5)\n    reg [3:0] our_state, opp_state;\n    always @(*) begin\n        our_state = 3'd0;\n        opp_state = 3'd0;\n        \n        // Our state mapping\n        case (our_sorted1)\n            4'd0: our_state = 3'd0;\n            4'd1: begin\n                case (our_sorted2)\n                    4'd0: our_state = 3'd1;\n                    default: our_state = 3'd2;\n                endcase\n            end\n            4'd2: begin\n                case (our_sorted2)\n                    4'd0: our_state = 3'd3;\n                    4'd1: our_state = 3'd4;\n                    default: our_state = 3'd5;\n                endcase\n            end\n            default: our_state = 3'd0;\n        endcase\n        \n        // Opponent state mapping\n        case (opp_sorted1)\n            4'd0: opp_state = 3'd0;\n            4'd1: begin\n                case (opp_sorted2)\n                    4'd0: opp_state = 3'd1;\n                    default: opp_state = 3'd2;\n                endcase\n            end\n            4'd2: begin\n                case (opp_sorted2)\n                    4'd0: opp_state = 3'd3;\n                    4'd1: opp_state = 3'd4;\n                    default: opp_state = 3'd5;\n                endcase\n            end\n            default: opp_state = 3'd0;\n        endcase\n    end\n\n    // Compute flattened index: (our_state * 6 + opp_state) * 11 + damage\n    wire [10:0] index;\n    assign index = (our_state * 6 + opp_state) * 11 + damage;\n\n    // Lookup probability from ROM (case statement)\n    always @(*) begin\n        case (index)\n            11'd222: probability_out = 32'h00005555;  // 1/3 in Q0.32\n            11'd385: probability_out = 32'h00000000;  // 0\n            default: probability_out = 32'h00000000;\n        endcase\n    end\n\nendmodule